struct Font far * far font_DumpFont(struct Font far *font)
{
    struct Font far *p;

    p = font;
    if (p) {
        if (p->glyphs)
            mem_free(p->glyphs);
        if (p->widths)
            mem_free(p->widths);
        if (p->offsets)
            mem_free(p->offsets);
        if (p)
            mem_free(p);
    }
    return 0;
}
